import { WgslTypeError } from "../errors.js";
import { validateProp } from "../nameUtils.js";
import { getName, setName } from "../shared/meta.js";
import { $gpuCallable, $gpuCallableStrictSignature, $internal } from "../shared/symbols.js";
import { tryConvertSnippet } from "../tgsl/conversion.js";
import { schemaCallWrapper } from "./schemaCallWrapper.js";
import { fallthroughCopyOrigin, snip } from "./snippet.js";
// ----------
// Public API
// ----------
/**
 * Creates a struct schema that can be used to construct GPU buffers.
 * Ensures proper alignment and padding of properties (as opposed to a `d.unstruct` schema).
 * The order of members matches the passed in properties object.
 *
 * @example
 * const CircleStruct = d.struct({ radius: d.f32, pos: d.vec3f });
 *
 * @param props Record with `string` keys and `TgpuData` values,
 * each entry describing one struct member.
 */
/*#__NO_SIDE_EFFECTS__*/
export function struct(props) {
    if (Object.keys(props).length === 0) {
        throw new Error('Cannot create struct schema with no properties.');
    }
    return INTERNAL_createStruct(props, false);
}
/*#__NO_SIDE_EFFECTS__*/
export function abstruct(props) {
    return INTERNAL_createStruct(props, true);
}
// --------------
// Implementation
// --------------
export function INTERNAL_createStruct(props, isAbstruct) {
    Object.keys(props).forEach((key) => {
        const result = validateProp(key);
        if (!result.success) {
            throw new Error(`Invalid property key '${key}'${result.error ? `: ${result.error}` : ''}`);
        }
    });
    // In the schema call, create and return a deep copy
    // by wrapping all the values in corresponding schema calls.
    const structSchema = (instanceProps) => Object.fromEntries(Object.entries(props).map(([key, schema]) => [
        key,
        schemaCallWrapper(schema, instanceProps?.[key]),
    ]));
    Object.setPrototypeOf(structSchema, WgslStructImpl);
    structSchema.propTypes = props;
    Object.defineProperty(structSchema, $internal, {
        value: {
            isAbstruct,
        },
    });
    return structSchema;
}
const WgslStructImpl = {
    type: 'struct',
    $name(label) {
        setName(this, label);
        return this;
    },
    toString() {
        return `struct:${getName(this) ?? '<unnamed>'}`;
    },
    get [$gpuCallableStrictSignature]() {
        return { argTypes: [this], returnType: this };
    },
    [$gpuCallable](ctx, args) {
        if (args.length > 1) {
            throw new WgslTypeError('Struct schemas should always be called with at most 1 argument');
        }
        // No arguments `Struct()`, resolve struct name and return.
        if (!args[0]) {
            // The schema becomes the data type.
            return ctx.gen.typeInstantiation(this, []);
        }
        const arg = tryConvertSnippet(ctx, args[0], this);
        // Either `Struct({ x: 1, y: 2 })`, or `Struct(otherStruct)`.
        // In both cases, we just let the argument resolve everything.
        return snip(ctx.resolveSnippet(arg).value, this, 
        // A new struct, so not a reference.
        /* origin */ fallthroughCopyOrigin(arg.origin), arg.possibleSideEffects);
    },
};
// Schemas are still functions, so they should keep `call`, `apply`, `bind`, etc.
Object.setPrototypeOf(WgslStructImpl, Function.prototype);
